package org.apache.commons.math3.distribution;

import org.apache.commons.math3.exception.DimensionMismatchException;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_11_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        double[] means = {0.0, 0.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        double[] vals = {1.0, 1.0};
        double incorrectExpectedDensity = 0.09653235263005391; // Incorrect value based on pre-fix formula
        double actualDensity = distribution.density(vals);

        assertEquals("Density calculation is incorrect", incorrectExpectedDensity, actualDensity, 1e-9);
    }
}

